xinshengCustomCss:
/* --- 全局直角 & 背景设置 --- */
.xt-root {
    padding: 0 !important; 
    background: #ffffff !important; 
    --xt-bg: #ffffff;
    border-radius: 0 !important; 
    max-width: 280px !important; 
    margin: 0 auto;
    box-shadow: 0 4px 20px rgba(0,0,0,0.1);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

.xt-card-title { display: none; }
.xt-spacer { background-color: #f2f2f2 !important; margin: 0; width: 100%; }

/* --- 强力清除系统默认灰底 --- */
.xt-text-currentDate, .xt-text-currentTime, .xt-text-accountId, .xt-text-postContent, .xt-text-commentTime, .xt-text-commentBody, .xt-text-commentCount {
    background: transparent !important;
    border-radius: 0 !important;
}

/* --- 头像绝对是圆的！ --- */
.xt-avatar {
    border-radius: 50% !important; 
    border: none !important;
    object-fit: cover !important;
}

/* 顶部栏 */
.xt-text-topTitle {
    text-align: center; font-size: 14px; font-weight: 500; color: #333;
    padding: 14px; margin: 0;
    background: #ffffff !important;
    border-radius: 0 !important;
    border-bottom: 2px solid #f2f2f2; 
    position: relative;
}
.xt-text-topTitle::before {
    content: ""; position: absolute; left: 16px; top: 18px; width: 8px; height: 8px;
    border-left: 2px solid #333; border-bottom: 2px solid #333; transform: rotate(45deg);
}

/* =========================================
   1. 顶部推文区 (以你为准：顶端对齐 + 紧紧挨着) 
   ========================================= */
.xt-text-topTitle + .xt-header { 
    padding: 16px 16px 0 16px !important; 
    align-items: flex-start !important; /* 顶端对齐 */
    gap: 0 !important; 
    margin: 0 !important;
    /* 删除了破坏排版的 flex-wrap 和 float */
}
.xt-text-topTitle + .xt-header .xt-avatar { 
    width: 40px !important; 
    height: 40px !important; 
    min-width: 40px !important; 
    margin: 0 !important;
} 
/* 昵称：干干净净的设定 */
.xt-text-topTitle + .xt-header .xt-name { 
    font-size: 15px !important; 
    font-weight: 600 !important; 
    color: #111 !important; 
    margin: 0 0 0 8px !important; /* 顶部0，左侧8px */
    padding: 0 !important;
    line-height: 1.2 !important; 
}

/* @ID：提拉进入空隙，紧挨昵称 */
.xt-text-accountId { 
    font-size: 11px !important; 
    color: #999 !important; 
    padding: 0 16px 8px 0 !important; /* 左内边距清零 */
    margin-left: 64px !important; /* 尺子一样的对齐：16+40+8=64px */
    margin-top: -20px !important; /* 【核心魔法】提拉 20px，完美吸附在名字下方！ */
    margin-bottom: 0 !important;
    text-align: left !important; 
    display: block !important;
    box-sizing: border-box !important;
}

/* 正文字体 18px */
.xt-text-postContent { font-size: 18px !important; color: #111 !important; padding: 4px 16px 12px 16px !important; line-height: 1.6 !important; margin: 0 !important; font-weight: 400 !important; text-align: left !important; }

/* 实时时间 & SVG 闹钟 */
.xt-text-currentDate { display: inline-block; padding: 0 4px 16px 32px !important; font-size: 10px !important; color: #b0b0b0 !important; margin: 0 !important; position: relative; }
.xt-text-currentDate::before {
    content: ""; position: absolute; left: 16px; top: 2.5px; 
    width: 11px; height: 11px;
    background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23b0b0b0" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>') no-repeat center/contain;
}
.xt-text-currentTime { display: inline-block; padding: 0 16px 16px 0 !important; font-size: 10px !important; color: #b0b0b0 !important; margin: 0 !important; }

/* 底部操作图标 */
.xt-tags { padding: 12px 16px !important; margin: 0 !important; border-top: 2px solid #f2f2f2 !important; display: flex; justify-content: space-between; }
.xt-tag { color: #888 !important; font-size: 12px !important; padding: 0 0 0 18px !important; border: none !important; background-color: transparent !important;}
.xt-tag:nth-child(1) { background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23888" stroke-width="2"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>') no-repeat left center/14px 14px !important; }
.xt-tag:nth-child(2) { background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23888" stroke-width="2"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg>') no-repeat left center/14px 14px !important; }
.xt-tag:nth-child(3) { background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23888" stroke-width="2"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>') no-repeat left center/14px 14px !important; }

/* =========================================
   2. 评论区 (以你为准：顶端对齐 + 紧紧挨着) 
   ========================================= */
.xt-text-commentCount { font-size: 12px !important; color: #999 !important; padding: 12px 16px 8px 16px !important; margin: 0 !important; border-bottom: 2px solid #f2f2f2 !important; }

.xt-text-commentCount ~ .xt-header { 
    padding: 12px 16px 0 16px !important; 
    align-items: flex-start !important; 
    gap: 0 !important; 
    margin: 0 !important; 
}
.xt-text-commentCount ~ .xt-header .xt-avatar { 
    width: 24px !important; 
    height: 24px !important; 
    min-width: 24px !important; 
    margin: 0 !important;
} 
/* 评论昵称 */
.xt-text-commentCount ~ .xt-header .xt-name { 
    font-size: 13px !important; 
    font-weight: normal !important; 
    color: #555 !important; 
    margin: 0 0 0 8px !important; /* 顶部0，左侧8px */
    padding: 0 !important;
    line-height: 1.2 !important; 
}

/* 评论文字：提拉进入空隙 */
.xt-text-commentBody { 
    font-size: 13px !important; 
    color: #333 !important; 
    padding: 0 16px 12px 0 !important; /* 左内边距清零 */
    margin-left: 48px !important; /* 尺子一样的对齐：16+24+8=48px */
    margin-top: -8px !important; /* 【核心魔法】提拉 8px，完美吸附在名字下方！ */
    margin-bottom: 0 !important; 
    line-height: 1.5 !important; 
    text-align: left !important; 
    box-sizing: border-box !important;
}

/* 评论时间、闹钟、点 */
.xt-text-commentTime { font-size: 10px !important; color: #ccc !important; text-align: right !important; padding: 0 30px 0 16px !important; margin-top: -22px !important; position: relative; }
.xt-text-commentTime::before {
    content: ""; display: inline-block; width: 10px; height: 10px; margin-right: 4px; vertical-align: -1.5px;
    background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23ccc" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>') no-repeat center/contain;
}
.xt-text-commentTime::after {
    content: ""; position: absolute; right: 14px; top: -1px; width: 14px; height: 14px;
    background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="%23ccc"><circle cx="12" cy="5" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="12" cy="19" r="2"/></svg>') no-repeat center/contain;
}

/* =========================================
   3. 底部输入区 (换上了无敌逼真的 SVG 纸飞机图标)
   ========================================= */
.xt-card { 
    background: #f4f4f4 !important; margin: 0 !important; padding: 10px 8px !important; 
    border-radius: 0 !important; border: none !important; position: relative !important; box-shadow: none !important; 
}
.xt-card .xt-text-inputText {
    background: #ffffff !important; 
    margin: 0 69px 0 0 !important; /* 给变宽了的发送按钮多留一点点空间 */
    padding: 10px !important; 
    border-radius: 4px !important; 
    font-size: 12px !important; 
    line-height: 1.5 !important;
    color: #333 !important; 
    border: 1px solid #e0e0e0 !important;
    min-height: 32px !important; 
    box-sizing: border-box !important; 
    display: block !important; 
    text-align: left !important;
}

/* 完美重构的发送键：SVG 图标 + 纯文字 */
.xt-card::after {
    content: "发送"; /* 去掉文本箭头，只留文字 */
    position: absolute; 
    right: 8px; 
    top: 10px; 
    background: #07c160 url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="%23ffffff"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>') no-repeat 10px center / 14px 14px !important; /* 插入白色的矢量纸飞机图标 */
    color: #fff; 
    padding: 0 12px 0 28px; /* 左边预留出28px专门放图标 */
    height: 30px; 
    line-height: 30px;
    border-radius: 4px; 
    font-size: 13px; 
    font-weight: bold;
}

